codeExamples.code:
-- Enable CBO and join reorder
SET spark.sql.cbo.enabled = true;
SET spark.sql.cbo.joinReorder.enabled = true;

-- Table-level and column-level statistics
ANALYZE TABLE sales COMPUTE STATISTICS;
ANALYZE TABLE sales COMPUTE STATISTICS FOR COLUMNS customer_id, order_date, amount;

-- Verify what the optimizer knows
DESCRIBE EXTENDED sales;
